from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]

    def edge_runs(row):
        runs = []
        c = 0
        while c < w:
            color = row[c]
            end = c + 1
            while end < w and row[end] == color:
                end += 1
            if color != background and end - c >= 2:
                runs.append((color, c, end - 1))
            c = end
        return runs

    top_runs = edge_runs(grid[0])
    bottom_runs = edge_runs(grid[-1])
    bar_colors = {run[0] for run in top_runs + bottom_runs}
    markers = [cell for row in grid for cell in row
               if cell != background and cell not in bar_colors]
    if not markers:
        return out
    line_color = Counter(markers).most_common(1)[0][0]

    def draw_ray(col, rows, bar_color):
        for r in rows:
            cell = grid[r][col]
            if cell != background:
                if cell != bar_color:
                    out[r][col] = 4
                break
            out[r][col] = line_color

    for color, left, right in top_runs:
        for col in {left, right}:
            draw_ray(col, range(1, h), color)

    for color, left, right in bottom_runs:
        for col in {left, right}:
            draw_ray(col, range(h - 2, -1, -1), color)

    return out
